fn main() -> Result<(), Box<dyn std::error::Error>> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../apps/desktop/src/generated/types.ts");
    let content = format!(
        "// Generated by cargo run -p prism-core --example export_types. Do not edit.\n{}",
        prism_core::typescript_definitions()
    );
    std::fs::create_dir_all(path.parent().ok_or("missing parent directory")?)?;
    std::fs::write(path, content)?;
    Ok(())
}
